def canonical_country_name(value: str) -> str:
    value = str(value or "").strip()
    if not value:
        return ""
    code = value.upper() if len(value) == 2 and value.upper() in set(COUNTRY_ALIASES.values()) else COUNTRY_ALIASES.get(value)
    if not code:
        folded = value.casefold()
        for alias, alias_code in COUNTRY_ALIASES.items():
            if alias.casefold() == folded:
                code = alias_code
                break
    if not code:
        raise ValueError("Pays non reconnu. Sélectionnez un pays dans la liste KalanPro.")
    # Le premier nom déclaré pour ce code est la valeur canonique.
    for name in COUNTRY_NAMES:
        if COUNTRY_ALIASES.get(name) == code:
            return name
    return value
